155	  task init_mem;
156	    input      [META_FNAME_SIZE*8-1:0] fn_metadata;
157	    input      [DATA_FNAME_SIZE*8-1:0] fn_data;
158	    reg [63:0] buf_num_soft;
159	    reg [31:0] data         [DATADATA_SIZE-1:0];
160	    reg [31:0] metadata     [METADATA_SIZE-1:0];
161	    reg [63:0] buf_ba_w     [BUF_NUM-1:0]; //buffer's base addr
162	    reg [63:0] buf_size     [BUF_NUM-1:0]; //buffer's size
163	    reg [63:0] buf_size_tmp [BUF_NUM-1:0]; //size align
164	    reg [63:0] buf_asize    [BUF_NUM-1:0]; //buffer's allocate size
165	    reg [63:0] burst_len    [BUF_NUM-1:0]; //burst len
166	    reg [63:0] burst_len_div[BUF_NUM-1:0];
167	    reg [63:0] burst_len_mod[BUF_NUM-1:0];
168	    reg [63:0] burst_times  [BUF_NUM-1:0];
169	    reg [63:0] burst_data   /*[BUF_NUM-1:0]*/;
170	    reg [32:0] addr;
171	    integer i, j, k, l, m;
172	    begin
173	      $readmemh(fn_data, data);
174	      $readmemh(fn_metadata, metadata);
175	      buf_num_soft = {metadata[27], metadata[26]};
176	
177	      //buffer base addr init
178	      for(i=0; i<buf_num_soft; i=i+1) begin
179	        buf_ba_w[i] = {metadata[i*2+29], metadata[i*2+28]};
180	      end
181	
182	      //buffer size init
183	      for(i=0; i<buf_num_soft; i=i+1) begin
184	        buf_size[i] = {metadata[i*2+29+(buf_num_soft*2)], metadata[i*2+28+(buf_num_soft*2)]};
185	      end
186	
187	      //buffer allocate size init,unused
188	      for(i=0; i<buf_num_soft; i=i+1) begin
189	        buf_asize[i] = {metadata[i*2+29+buf_num_soft*4], metadata[i*2+28+buf_num_soft*4]};
190	      end
191	      
192	      for(i=0;i<buf_num_soft;i=i+1) begin
193	        buf_size_tmp[i] = (buf_size[i]%4==0) ? buf_size[i] : (buf_size[i]/4)*4+4;
194	        burst_len[i] = buf_size_tmp[i]/4;
195	        burst_len_div[i] = burst_len[i]/16;
196	        burst_len_mod[i] = burst_len[i]%16;
197	        burst_times[i] = (burst_len_mod[i]==0) ? burst_len_div[i] : burst_len_div[i]+1;
198	        //burst_data[i] = (burst_len_mod[i]==0) ? 16 : (k<burst_times[j]-1) ? 16 : burst_len_mod[i];
199	      end 
200	
201	      j=0; //buf_num cnt
202	      m=0;
203	      while(j<buf_num_soft) begin
204	        force u_ram.s_axi_bready  = 1'd1;
205	        k=0;
206	        while(k<burst_times[j]) begin
207	          @(posedge clk);
208	          if(burst_len_mod[j]==0) begin
209	            force u_ram.s_axi_awvalid = 1'd1;
210	            force u_ram.s_axi_awid    = 4'd0;
211	            force u_ram.s_axi_awaddr  = (k==0) ? buf_ba_w[j] : addr+16*4;//start address
212	            force u_ram.s_axi_awlen   = 8'hf; //16 times
213	            force u_ram.s_axi_awsize  = 3'd2; //4bytes
214	            force u_ram.s_axi_awburst = 2'd1; //INCR
215	          end
216	          else begin
217	            force u_ram.s_axi_awvalid = 1'd1;
218	            force u_ram.s_axi_awid    = 4'd0;
219	            force u_ram.s_axi_awaddr  = (k==0) ? buf_ba_w[j] : addr+16*4;//start address
220	            force u_ram.s_axi_awlen   = (k==(burst_times[j]-1))? burst_len_mod[j]-1 : 8'hf; 
221	            force u_ram.s_axi_awsize  = 3'd2; //4bytes
222	            force u_ram.s_axi_awburst = 2'd1; //INCR
223	          end 
224	          wait(u_ram.s_axi_awready==1'd1);
225	          @(posedge clk);
226	          addr                        = u_ram.s_axi_awaddr;
227	          release u_ram.s_axi_awvalid;
228	          release u_ram.s_axi_awid;   
229	          release u_ram.s_axi_awaddr; 
230	          release u_ram.s_axi_awlen;  
231	          release u_ram.s_axi_awsize;
232	          release u_ram.s_axi_awburst;
233	          l=0;
234	          burst_data = (burst_len_mod[j]==0) ? 16 : ((k<burst_times[j]-1) ? 16 : burst_len_mod[j]);
235	          while(l<burst_data) begin
236	            force u_ram.s_axi_wvalid  = 1'd1;
237	            force u_ram.s_axi_wdata   = (l%2==0) ? {32'd0,data[m]} : {data[m],32'd0};
238	            force u_ram.s_axi_wstrb   = (l%2==0) ? 8'hf : 8'hf0;
239	            if(l==burst_data-1)begin
240	              force u_ram.s_axi_wlast = 1'd1;
241	            end 
242	            wait(u_ram.s_axi_wready==1'd1);
243	            @(posedge clk);
244	            release u_ram.s_axi_wvalid;  
245	            release u_ram.s_axi_wdata;
246	            release u_ram.s_axi_wstrb;   
247	            release u_ram.s_axi_wlast;
248	            l=l+1;
249	            m=m+1;
250	          end 
251	          k=k+1;
252	        end
253	      wait(u_ram.s_axi_bvalid==1'd1);
254	      @(posedge clk);
255	      release u_ram.s_axi_bready;
256	      j=j+1;
257	      end 
258	    end
259	  endtask
